/* Local processing workflow. No roster is transmitted to a server. */
'use strict';
let processor, pendingBatch=null, workspaceWrite=Promise.resolve();
const BATCH_DB='sz-investment-local-batches-v2';
function batchDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(BATCH_DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function batchStorage(mode,value){const db=await batchDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('workspace',mode),s=tx.objectStore('workspace');let r=mode==='readonly'?s.get('active'):s.put(value,'active');tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('保存中断'))})}finally{db.close()}}
const originalUnitIssues=unitIssues,originalGuestIssues=guestIssues;
unitIssues=u=>[...new Set([...originalUnitIssues(u),...(u.processingIssues||[]),...(u.rankIssues||[]),...(u.country==='冲突待核对'?['单位国别冲突']:[])])];
guestIssues=g=>[...new Set([...originalGuestIssues(g),...(g.processingIssues||[]).filter(x=>!x.startsWith('已按精准职务')), ...(g.priorityReasons||[])])];
function recalculate(){D.guests=G;if(D.processing)processor.screen(D)}
save=function(){recalculate();const snapshot=structuredClone({format:'investment-workspace-v2',data:D,baseGuests:baseG,edits,log,reviewed});workspaceWrite=workspaceWrite.catch(()=>{}).then(()=>batchStorage('readwrite',snapshot)).catch(()=>toast('本机保存失败，请立即导出批次备份；当前页面仍可使用'));return true};
function updateBatchLabel(){document.querySelector('footer').innerHTML='数据截至 '+esc(D.baseline.date)+' · 规则 '+esc(D.baseline.ruleDate)+'<span>'+esc(D.baseline.source||'公开演示数据')+' · 本机处理</span>';document.querySelector('.private').textContent=D.processing?'本机数据':'演示数据'}
function applyBatch(data,backup){D=data;U=new Map(D.units.map(u=>[u.id,u]));G=D.guests;baseG=backup?.baseGuests||structuredClone(G);edits=backup?.edits||{};reviewed=backup?.reviewed||{};log=backup?.log||[];pendingBatch=null;query='';filter='all';page=1;updateBatchLabel();save();location.hash='#overview';render()}
renderImports=function(){const sheets=imported?.sheets||[];return header('数据导入','上传 → 规则处理 → 应用到工作台 → 核对与导出')+`<section class="panel"><div class="panel-body"><h2>导入原始填报表</h2><p>支持20MB以内的.xlsx。文件在本机浏览器中解析，不上传到公开仓库。按表头识别单位、嘉宾与参会状态；只传播实际合并单元格。</p><input id="file-input" type="file" accept=".xlsx" aria-label="上传原始Excel"><p id="import-status"></p><div class="notice">当前批次：${esc(D.baseline.source||'公开演示数据')} · ${yesUnits().length}家确认单位、${yes().length}位确认嘉宾。应用新批次会切换当前名单和核对草稿，建议先保存备份。</div><button class="btn" data-action="backup-batch">保存当前批次备份</button><label class="form-field">恢复批次备份<input id="backup-input" type="file" accept=".json"></label></div></section>${sheets.length?`<section class="panel" style="margin-top:20px"><div class="panel-body"><h2>${esc(imported.name)}</h2><p>选择参与统计的原始嘉宾工作表。表头必须包含“参会单位名称”“嘉宾姓名”“是否参加主会场”；单位汇总表不会重复计入。</p>${sheets.map((s,i)=>`<label class="form-field"><span><input type="checkbox" data-import-sheet="${i}" ${imported.matches.includes(i)?'checked':''}> ${esc(s.name)} · ${s.rows.length}行</span></label>`).join('')}<label class="form-field">数据截止时间（请按源表填写）<input id="batch-date" value="${esc(imported.date)}"></label><label class="form-field">额外名称对照（可选，每行“原名称=标准名称”；只合并已确认的同一主体）<textarea id="batch-aliases" rows="4" style="width:100%" placeholder="原名称=标准名称"></textarea></label><button class="btn primary" data-action="process-batch">按规则处理所选表</button></div></section>`:''}${pendingBatch?`<section class="panel" style="margin-top:20px"><div class="panel-body"><h2>处理结果 · 尚未应用</h2><p>确认参会单位 <b>${pendingBatch.baseline.units}</b> 家，确认嘉宾 <b>${pendingBatch.baseline.guests}</b> 人。待定 ${pendingBatch.guests.filter(g=>g.status==='待定').length} 人、空白 ${pendingBatch.guests.filter(g=>g.status==='空白').length} 人另列。</p><p>有效原始记录 ${pendingBatch.processing.validRows} 条；归并重复记录 ${pendingBatch.processing.mergedRows} 条；排除模板/说明行 ${pendingBatch.processing.excluded.length} 条。</p><p>应用后，全部统计、名单及文件导出将使用该批次。异常与缺失信息进入“信息核对”。</p><button class="btn primary" data-action="apply-batch">应用到工作台并替换当前批次</button></div></section>`:''}`};
const oldBindInputs=bindInputs;
bindInputs=function(){oldBindInputs();$('#file-input')?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;$('#import-status').textContent='正在读取工作表…';pendingBatch=null;try{const sheets=await XlsxReader.read(f);let parsed;try{parsed=processor.parseSheets(sheets,D)}catch{parsed={sheets:[]}}imported={name:f.name,sheets,matches:parsed.sheets,date:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})};render();toast(parsed.sheets.length?'文件已读取，请检查工作表和截止时间后处理':'未自动识别嘉宾表，请检查表头')}catch(err){$('#import-status').textContent='读取失败：'+err.message;toast(err.message)}});$('#backup-input')?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>30*1024*1024)throw Error('备份超过30MB');const b=JSON.parse(await f.text());validateBackup(b);applyBatch(b.data,b);toast('已恢复本机批次')}catch(err){toast('恢复失败：'+err.message)}})};
function validateBackup(b){if(b?.format!=='investment-workspace-v2'||!Array.isArray(b.data?.units)||!Array.isArray(b.data?.guests)||!Array.isArray(b.baseGuests))throw Error('不是有效的工作台批次备份');const d=b.data,ids=new Set();for(const u of d.units){if(!/^[\w-]+$/.test(u.id)||ids.has(u.id)||!Array.isArray(u.lines)||!['name','short','type','country','industry'].every(k=>typeof u[k]==='string'))throw Error('单位数据格式无效');ids.add(u.id)}const gs=new Set();for(const g of d.guests){if(!/^[\w-]+$/.test(g.id)||gs.has(g.id)||!ids.has(g.unitId)||!['是','否','待定','空白'].includes(g.status)||!Array.isArray(g.owners)||!Array.isArray(g.lines)||!['name','title','nationality'].every(k=>typeof g[k]==='string'))throw Error('嘉宾数据格式无效');gs.add(g.id)}if(!d.baseline||!Array.isArray(d.departments)||!Array.isArray(d.districts)||!Array.isArray(d.rules)||d.guests.length>20000||d.units.length>20000)throw Error('批次结构无效');for(const g of b.baseGuests)if(!gs.has(g.id))throw Error('原始嘉宾不匹配')}
const originalOverview=overview;
overview=function(){return originalOverview().replace('11月18日汇总名单',esc(D.baseline.source||'公开演示数据'))+`<div class="notice">含待定、空白暂计：${new Set(G.filter(g=>g.status!=='否').map(g=>g.unitId)).size}家单位、${G.filter(g=>g.status!=='否').length}人；剔除暂计：${yesUnits().length}家单位、${yes().length}人。总裁及副总裁以上：${yes().filter(g=>g.senior).length}人。</div>`};
reportText=function(){const gs=yes(),us=yesUnits(),companies=us.filter(u=>u.type==='意向投资企业'),nat=n=>gs.filter(g=>g.nationality===n).length,known=g=>!missing(g.nationality)&&!['中国','中国香港','中国澳门','中国台湾'].includes(g.nationality),countNature=regex=>companies.filter(u=>regex.test(u.primaryNature)).length,industries={};for(const u of companies)industries[u.industry]=(industries[u.industry]||0)+1;return `2026年深圳全球招商大会嘉宾邀请进展（核对稿）\n数据截至：${D.baseline.date}\n源文件：${D.baseline.source||'公开演示数据'}\n规则版本：${D.baseline.ruleDate}\n一、确认参会单位\n确认参会单位${us.length}家，其中企业${companies.length}家、招商合作机构${us.filter(u=>u.type==='招商合作机构').length}家。世界500强外资企业${countNature(/^1\./)}家、世界500强内资企业${countNature(/^2\./)}家、中国民营企业500强${countNature(/^3\./)}家、央国企${countNature(/^[58]\./)}家（按唯一主分类，榜单标签重叠另行核对）。\n企业数量最多的行业：${Object.entries(industries).filter(([n])=>!missing(n)).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([n,c])=>n+c+'家').join('、')}。\n二、确认参会嘉宾\n确认参会嘉宾${gs.length}人，其中总裁及副总裁以上${gs.filter(g=>g.senior).length}人，重点嘉宾${gs.filter(g=>g.priority).length}人。中国香港${nat('中国香港')}人、中国澳门${nat('中国澳门')}人、中国台湾${nat('中国台湾')}人；外籍${gs.filter(known).length}人，国籍或地区未知${gs.filter(g=>missing(g.nationality)).length}人。\n三、暂计项与资料完善\n参会状态待定${G.filter(g=>g.status==='待定').length}人、空白${G.filter(g=>g.status==='空白').length}人。含上述暂计项的参会总人数${G.filter(g=>g.status!=='否').length}人、单位${new Set(G.filter(g=>g.status!=='否').map(g=>g.unitId)).size}家；剔除暂计项为${gs.length}人、${us.length}家。姓名、职务、国籍至少一项未落实的确认记录${gs.filter(g=>originalGuestIssues(g).length).length}条，已包含在确认人数中。\n四、各区邀请进展\n${departmentRows('district').map(d=>`${d.label}：确认单位${d.units}家、嘉宾${d.guests}人，任务完成率${d.rate.toFixed(1)}%。`).join('\n')}\n五、市直单位邀请进展\n${departmentRows('city').map(d=>`${d.label}：确认单位${d.units}家、嘉宾${d.guests}人，任务完成率${d.rate.toFixed(1)}%。`).join('\n')}\n统计口径：仅参会状态“是”计入确认；资料缺失不扣减，缺失人选为暂计名额。同企业同名按规则去重，邀请来源保留；各部门内去重，跨部门成果可重复。异常冲突需核对后形成正式汇报。`};
const originalExport=exportData;
exportData=function(a){if(a==='export-priority'){const order={A:0,B:1,C:2};const gs=yes().filter(g=>g.priority).sort((a,b)=>(order[a.priorityTier]??0)-(order[b.priorityTier]??0));const f=Office.xlsx(['企业全称','企业简称','企业类型','嘉宾姓名','嘉宾职务'],guestRows(gs),'重点嘉宾名单');Office.download(f.blob,f.name);return}originalExport(a)};
const originalGuestDrawer=guestDrawer;
guestDrawer=function(id){originalGuestDrawer(id);const p=$('#guest-form .tiny');if(p)p.textContent='保存后自动更新本机统计和重点、高管标签；新职务仍需按业务依据核实。'};
const originalUnitDrawer=unitDrawer;
unitDrawer=function(id){originalUnitDrawer(id);const u=unit(id),form=document.createElement('form');form.id='unit-edit-form';form.innerHTML=`<h3>核对单位资料</h3>${[['name','单位标准名称'],['short','单位简称'],['country','国家 / 地区'],['primaryNature','企业性质（带编号）'],['institution','机构性质'],['industry','标准行业']].map(([k,l])=>`<label class="form-field">${l}<input name="${k}" value="${esc(u[k]||'')}"></label>`).join('')}<label class="form-field">单位类型<select name="type">${['意向投资企业','招商合作机构','类型待核对'].map(t=>`<option ${u.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="form-field">核对依据<input name="evidence" required></label><p class="tiny">此处修改展示资料，不自动合并独立主体。企业归并请在导入页填写名称对照后重算。</p><button class="btn primary">保存单位资料并重算标签</button>`;$('#drawer').appendChild(form);form.addEventListener('submit',e=>{e.preventDefault();const patch=Object.fromEntries(new FormData(form));if(!patch.evidence.trim())return;const before=structuredClone(u);for(const k of ['name','short','country','primaryNature','institution','industry','type'])u[k]=patch[k].trim();u.processingIssues=[];u.rankIssues=[];log.push({time:new Date().toISOString(),unit:id,before,after:structuredClone(u),evidence:patch.evidence});save();closeDrawer();render();toast('单位资料已保存，统计已更新')})};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;try{if(b.dataset.action==='process-batch'){const selected=[...document.querySelectorAll('[data-import-sheet]:checked')].map(x=>+x.dataset.importSheet);if(!selected.length)throw Error('请至少选择一张嘉宾表');const parsed=processor.parseSheets(imported.sheets,D,selected),aliases={};for(const line of $('#batch-aliases').value.split('\n').filter(x=>x.trim())){const i=line.indexOf('=');if(i<1||!line.slice(i+1).trim())throw Error('名称对照格式应为：原名称=标准名称');aliases[Processing.key(line.slice(0,i))]=line.slice(i+1).trim()}imported.date=$('#batch-date').value.trim();if(!imported.date)throw Error('请填写数据截止时间');pendingBatch=processor.fromRecords(parsed.records,D,{fileName:imported.name,date:imported.date,aliases});if(!pendingBatch.guests.length)throw Error('没有识别到有效嘉宾记录');render();toast('处理完成，请核对结果后应用')}if(b.dataset.action==='apply-batch'&&pendingBatch){applyBatch(pendingBatch);toast('新批次已应用，统计与导出已更新')}if(b.dataset.action==='backup-batch'){const b={format:'investment-workspace-v2',data:{...D,guests:G},baseGuests:baseG,edits,log,reviewed};Office.download(new Blob([JSON.stringify(b)],{type:'application/json'}),'参会工作台批次备份.json')}}catch(err){toast('处理失败：'+err.message)}});
init=async function(){try{const [r,c]=await Promise.all([fetch('data.json'),fetch('processing-rules.json')]);if(!r.ok||!c.ok)throw Error('数据或规则加载失败');const demo=await r.json();processor=Processing.create(await c.json());let saved;try{saved=await batchStorage('readonly');if(saved)validateBackup(saved)}catch{saved=null;toast('本机批次未能恢复，已打开演示数据')}D=saved?.data||demo;U=new Map(D.units.map(u=>[u.id,u]));G=D.guests;baseG=saved?.baseGuests||structuredClone(G);edits=saved?.edits||{};reviewed=saved?.reviewed||{};log=saved?.log||[];recalculate();updateBatchLabel();render()}catch(err){$('#main').innerHTML=`<div class="empty">${esc(err.message)}，请刷新重试。</div>`}};
init();
